contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to make c send money out. The caller provides target, amount to send, and an initial funding value.
    // The contract under test P only allows the owner to move funds out; the mutant M allows anyone.
    function run(address payable target, uint256 sendAmount, uint256 fundAmount) public payable {
        // require this test contract has enough ETH to fund C
        require(address(this).balance >= fundAmount, "insufficient balance to fund C");
        // fund C by invoking fallback with value
        (bool s1, ) = address(c).call{value: fundAmount}("");
        require(s1, "funding failed");

        // record balance before attempting to make C send out
        uint256 before = address(c).balance;

        // attempt to make C send funds to target using sendMoney (which under P is onlyOwner-protected)
        // This is the distinguishing call: under P it will revert (if caller not owner) or succeed only for owner.
        // We do the call as this (non-owner) contract.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, sendAmount));

        // observe balance after the call
        uint256 after = address(c).balance;

        // General rule: if the call came from a non-owner (this contract), C's balance must not decrease
        // i.e., after >= before. This holds for original contract P, but is violated by mutant M.
        assert(after >= before);
    }

    // so this contract can receive ether for funding the test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        // we must call withdrawAll from the specified caller; emulate by using delegatecall-style via a helper contract is not allowed.
        // Instead, use that this test contract is not the owner (deployer of C). So require caller == address(this) to represent a non-owner caller.
        // Ensure this test contract is the caller: require caller == address(this)
        require(caller == address(this));
        // Call withdrawAll and record whether it reverted. On original P this should revert when called by non-owner; on mutant M it will succeed.
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // The rule: if the caller is not the deployer/owner, the call must revert. We cannot read owner, so express that for any caller different from address(this) would be meaningless here.
        // Since we constrained caller == address(this), assert that the call reverted (i.e., non-owner cannot withdrawAll).
        assert(reverted == true);
    }
    receive() external payable {}
}

contract InvMutTest {
