    // We need at least one fuzz parameter; use uint256 depositAmount and address recipient
    function testFuzz_property(uint256 depositAmount, address recipient) public {
        // keep depositAmount within reasonable bounds but allow wide range
        depositAmount = bound(depositAmount, 0, 1 ether);
        // recipient must be a contract for the difference to manifest; fuzzed address may be EOA
        // deploy an adversarial recipient that will revert in receive() to break transfer but not low-level call
        Reverter rev = new Reverter();

        address target = recipient;
        // If the fuzzed recipient happens to equal address(0) or an EOA, still test with the adversary to ensure we cover break case
        // We will pass the adversary's address into sendMoney to make it the eventual recipient of funds via withdrawAll
        // Fund the contract by calling fallback via sending ether (owner is this test deployer by default in setUp)
        // Make sure the test contract (which deployed C) is the owner; setUp used new C() so owner is address(this)

        // deposit funds into c by sending ether to its fallback
        if (depositAmount > 0) {
            // give this test address enough balance
            vm.deal(address(this), depositAmount);
            // send the funds to the contract to trigger fallback which increments depositsCount
            (bool sent,) = address(c).call{value: depositAmount}("");
            require(sent);
        }

        // Now instruct c to send money to our adversarial recipient using sendMoney
        // sendMoney requires onlyOwner, and this test contract is the owner
        // Use the adversarial reverter as the target to simulate a recipient that will revert on transfer
        c.sendMoney(address(rev), 0); // just ensure sendMoney works for zero value first

        // Now call withdrawAll and observe whether it succeeds (true) or reverts (false)
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general property: in the reference implementation withdrawAll uses low-level call and should NOT revert
        // for any recipient; thus ok must be true for all admissible inputs. The mutant using transfer may revert
        // when the recipient reverts on receive(), making ok == false for some inputs. Assert that ok is true.
        assertTrue(ok);
    }
}

