    function setUp() public { c = new C(); }

    // Fuzz parameters: attacker address and an amount to fund the contract.
    // The general rule: only the owner (deployer) can withdrawAll. On the reference this holds
    // for all inputs; the mutant (which removes onlyOwner) allows some attacker to succeed.
    function testFuzz_property(address attacker, uint256 fundAmount) public {
        // keep fundAmount in a reasonable range but wide
        fundAmount = bound(fundAmount, 0, 1 ether);
        // attacker must be a non-zero address and not the owner to be meaningful
        vm.assume(attacker != address(0));
        vm.assume(attacker != address(this));
        vm.assume(attacker != address(c));

        // Fund the attacker so they can send ether to the contract if needed
        vm.deal(attacker, fundAmount);

        // Deposit funds into contract by calling fallback via a call with value from attacker
        vm.prank(attacker);
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent);

        // Record contract balance before withdrawAll
        uint256 before = address(c).balance;
        // Ensure there is something to withdraw in some cases; allow zero too

        // Now attacker calls withdrawAll (this should revert or be restricted on the reference)
        vm.prank(attacker);
        bool ok;
        try c.withdrawAll{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
