        (bool sentToC, ) = address(c).call{value: amount}("");
        require(sentToC);

        // Record c balance before forwarding
        uint256 before = address(c).balance;

        // Now instruct c to forward 'amount' to target. In the original contract this will revert if the external call fails,
        // so either the forward succeeds and c balance decreases by amount, or the call reverts and state is unchanged.
        // In the mutant, the external call may fail silently and c's balance would NOT decrease.
        c.sendMoney(target, amount);

