        uint256 after = address(c).balance;

        // Assert that c's balance decreased exactly by amount (i.e., forward succeeded), or call reverted and this line not reached.
        // This is a distinguishing rule: on original contract, if run continues past sendMoney, then funds were transferred.
        assert(before - after == amount);
    }

    // allow this contract to receive ether for the test harness
    receive() external payable {}
}

