        // To get the original balance, reconstruct from current contract balance plus either amount (if non-reverted)
        // Since we forwarded amount into c before the call, its balance before sendMoney was address(c).balance + (reverted?0:amount).
        // Simpler: capture balance before call by doing an explicit read before invoking sendMoney.
    }
    receive() external payable {}
}

