pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the amount to send and an arbitrary payer address
    function testFuzz_property(uint256 amount, address payer) public {
        // keep amount within contract-balance-sized bounds
        amount = bound(amount, 0, 1 ether);
        // payer should be non-zero
        vm.assume(payer != address(0));

        // deploy a callee that always reverts when receiving funds
        Reverter reverter = new Reverter();

        // fund the contract c so it has balance to send
        vm.deal(address(c), 1 ether);

        // attempt the external call and capture whether it reverted
        bool ok;
        try c.sendMoney(address(reverter), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): The reference contract always reverts (ok==false)
        // when the callee reverts; the mutant that removed the require will make ok==true for some inputs.
        // We assert the property that the correct contract's sendMoney call to a reverting callee does not succeed.
        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}
